_PAGE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#090d15"><title>Vishnu · Capability Forge</title><style>html,body{margin:0;min-height:100%;background:#090d15;color:#f6f8fc;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text",Inter,sans-serif}body:before{content:"Capability Forge";display:block;padding:24px;font-weight:800;font-size:18px;color:#aebbd0}</style></head><body><script>window.showToast=message=>console.info(message)</script><script src="/iphone/capability-forge-ui.js"></script></body></html>'''


class CapabilityForgeUiMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request, call_next):
        response = await call_next(request)
        if request.url.path not in {"/iphone", "/iphone/", "/capabilities", "/capabilities/"} or response.status_code != 200:
            return response
        if "text/html" not in response.headers.get("content-type", ""):
            return response
        body = b""
        async for chunk in response.body_iterator:
            body += chunk
        text = body.decode("utf-8")
        marker = "</body>"
        script = '<script src="/iphone/capability-forge-ui.js"></script>'
        if marker in text and script not in text:
            text = text.replace(marker, script + marker, 1)
        headers = {key: value for key, value in response.headers.items() if key.lower() not in {"content-length", "content-encoding"}}
        return Response(text, status_code=response.status_code, headers=headers, media_type="text/html")


def capability_forge_ui_router() -> APIRouter:
    router = APIRouter()

    @router.get("/iphone/capability-forge-ui.js", include_in_schema=False)
    def forge_ui_js():
        return Response(JS, media_type="application/javascript", headers={"Cache-Control": "no-cache"})

    @router.get("/capabilities/forge", response_class=HTMLResponse, include_in_schema=False)
    def forge_console_page():
        return HTMLResponse(_PAGE, headers={"Cache-Control": "no-store"})

    return router
